class Solution {
  public int minDays(int[][] grid) {
    if (count(grid) != 1) return 0;
    int m = grid.length, n = grid[0].length;
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++)
        if (grid[i][j] == 1) {
          grid[i][j] = 0;
          if (count(grid) != 1) {
            grid[i][j] = 1;
            return 1;
          }
          grid[i][j] = 1;
        }
    return 2;
  }

  private int count(int[][] g) {
    boolean[][] seen = new boolean[g.length][g[0].length];
    int c = 0;
    for (int i = 0; i < g.length; i++)
      for (int j = 0; j < g[0].length; j++)
        if (g[i][j] == 1 && !seen[i][j]) {
          c++;
          if (c > 1) return c;
          flood(g, seen, i, j);
        }
    return c;
  }

  private void flood(int[][] g, boolean[][] seen, int i, int j) {
    if (i < 0 || i == g.length || j < 0 || j == g[0].length || g[i][j] != 1 || seen[i][j]) return;
    seen[i][j] = true;
    flood(g, seen, i + 1, j);
    flood(g, seen, i - 1, j);
    flood(g, seen, i, j + 1);
    flood(g, seen, i, j - 1);
  }
}
